void swap(int x, int y)
{
    int temp;
    temp = x;
    x = y;
    y = temp;
}

main()
{
    int a = 5, b = 6;
    swap(a, b);       /* a = 5, b = 6: no cambian */
}

void swap(int *px, int *py)
{
    int temp;
    temp = *px;
    *px = *py;
    *py = temp;
}

main()
{
    int a = 5, b = 6;
    swap(&a, &b);     /* a = 6, b = 5: intercambiados */
}

