/* función que calcula el máximo de un vector */
int max(int *v, int tam)
{
    int maximo = 0;
    int i = 0;
    for (i = 0; i < tam; i++) {
        if (v[i] > maximo)
            maximo = v[i];
    }
    return (maximo);
}

